      "card_ids": ["C34"]
    },
    {
      "claim": "L2 animal/preclinical F values above 20% for other molecules (toceranib 76.9% in dogs, pyronaridine 35% in dogs, CDP323 >25% preclinically) reinforce that the low human F references are compound-specific and do not define the query.",
      "card_ids": ["C24", "C28", "C20"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
